const listIds = {
  "Document Request": "YOUR_DOCUMENT_REQUEST_LIST_ID",
  "Presentation Request": "YOUR_PRESENTATION_REQUEST_LIST_ID",
  "Update Request": "YOUR_UPDATE_REQUEST_LIST_ID",
  "Workflow Request": "YOUR_WORKFLOW_REQUEST_LIST_ID",
};
function typeformClickupRequest({ response, listIds }) {
  if (
    !response ||
    typeof response !== "object" ||
    Array.isArray(response) ||
    !Array.isArray(response.answers) ||
    !response.definition ||
    !Array.isArray(response.definition.fields)
  ) {
    throw new Error("Expected a complete Typeform response with answers and field definitions");
  }
  const titles = new Map(),
    answers = new Map();
  for (const field of response.definition.fields) {
    if (
      !field ||
      typeof field.id !== "string" ||
      typeof field.title !== "string" ||
      titles.has(field.id)
    )
      throw new Error("Invalid or duplicate Typeform field definition");
    titles.set(field.id, field.title);
  }
  for (const answer of response.answers) {
    if (
      !answer ||
      typeof answer !== "object" ||
      !answer.field ||
      typeof answer.field.id !== "string" ||
      typeof answer.type !== "string"
    )
      throw new Error("Invalid Typeform answer");
    const title = titles.get(answer.field.id);
    if (!title) continue;
    if (answers.has(title)) throw new Error("Duplicate answered question title: " + title);
    const value = answer[answer.type];
    answers.set(
      title,
      answer.type === "choice" && value && typeof value === "object" ? value.label : value,
    );
  }
  const category = answers.get("What type of a request are you making?");
  const categories = [
    "Document Request",
    "Presentation Request",
    "Update Request",
    "Workflow Request",
  ];
  if (!categories.includes(category))
    return {
      matched: false,
      listId: "UNROUTED",
      name: "Unrouted request",
      description: "",
      priority: null,
    };
  const listId = listIds?.[category];
  if (typeof listId !== "string" || !/^\d+$/.test(listId))
    throw new Error("Configure the ClickUp list ID for " + category);
  const requiredText = (title) => {
    const value = answers.get(title);
    if (typeof value !== "string" || !value.trim())
      throw new Error("Missing text answer: " + title);
    return value;
  };
  const name = requiredText("Give this request a short title.");
  const details = requiredText(
    "Describe in detail what you would like to see happen for this request.",
  );
  const requester = requiredText("Your full name"),
    email = requiredText("Your email address");
  const urgency = answers.get("How urgent is this request?");
  let priority = null;
  if (urgency !== undefined && urgency !== null && urgency !== "" && urgency !== 0) {
    if (!Number.isInteger(urgency) || urgency < 1 || urgency > 4)
      throw new Error(
        "Urgency must be a ClickUp priority number from1 to4, or blank/0 for no priority",
      );
    priority = urgency;
  }
  return {
    matched: true,
    listId,
    name,
    description: details + "\n\nRequested by:\n" + requester + "\n" + email,
    priority,
  };
}

return $input.all().flatMap((item, index) => {
  if (item.json.event_type !== "form_response") return [];
  const request = typeformClickupRequest({ response: item.json.form_response, listIds });
  return request.matched ? [{ json: request, pairedItem: { item: index } }] : [];
});

function clickupCreatedTask({ task }) {
  if (
    !task ||
    typeof task !== "object" ||
    Array.isArray(task) ||
    typeof task.id !== "string" ||
    !task.id.trim()
  )
    throw new Error("ClickUp did not return a created task ID");
  return { task };
}

return { json: clickupCreatedTask({ task: $json }).task };
